// Base — excerpted VERBATIM from the shipped family (one of its
// thirteen labels, with the real floors).
classifiers "APH_ACT_SCHEDULING" {
  labels {
    TIME_ACCEPTED {
      description = "Accepts a specific time the counterparty previously proposed, converting that proposal into a firm commitment for the sender's principal. This is the canonical 'accept meeting time' act. No new time is introduced and no condition is attached."
      examples    = ["Tuesday at 2pm works — I'm booking it.",
                     "Accept the meeting time as proposed.",
                     "Yes, Thursday 10:00 Eastern is confirmed on my side."]
    }
  }
}

// Overlay — a LATER entry for the SAME namespace, contributed by anyone.
// Adds a label the base does not define. This is the ONE additive direction
// in the lattice. The label below is HYPOTHETICAL and ships nowhere.
classifiers "APH_ACT_SCHEDULING" {
  labels {
    ACCEPT_WITH_TRAVEL_BUFFER {
      description = "HYPOTHETICAL, not shipped: accepts the proposed time but asserts a required buffer before or after."
      examples    = ["works if we can start 15 minutes late",
                     "yes, but I need a half hour after for travel",
                     "fine, just not back-to-back with the prior call"]
    }
  }
}
